// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import { viewLayoutChange } from "../../../main/frontend/graph-explorer/graph-model.ts";
import { projectCollections, RDF_FIRST, RDF_REST, RDF_NIL } from "../../../main/frontend/graph-explorer/graph-collections.ts";

const node = (id, kind = "iri") => ({ id, label: id, kind, x: 0, y: 0 });
const edge = (id, source, predicate, target) => ({ id, source, predicate, target, label: predicate });

test("edge-only list completion repairs the layout of the newly folded view", () => {
  const before = {
    nodes: [node("owner"), node("head", "blank"), node("tail", "blank"), node("a"), node("b"), node(RDF_NIL)],
    edges: [edge("owner-head", "owner", "members", "head"), edge("first-a", "head", RDF_FIRST, "a"),
      edge("rest-tail", "head", RDF_REST, "tail"), edge("first-b", "tail", RDF_FIRST, "b")],
    revision: 0,
  };
  const after = { ...before, edges: [...before.edges, edge("rest-nil", "tail", RDF_REST, RDF_NIL)], revision: 1 };
  assert.deepEqual(viewLayoutChange(projectCollections(before).graph, projectCollections(after).graph), { added: [], repair: true });
});

test("layout change distinguishes added cards from changed dimensions", () => {
  const before = { nodes: [node("a")], edges: [], revision: 0 };
  assert.deepEqual(viewLayoutChange(before, { ...before, nodes: [...before.nodes, node("b")] }), { added: ["b"], repair: false });
  assert.deepEqual(viewLayoutChange(before, { ...before, nodes: [{ ...before.nodes[0], label: "A label long enough to change the card dimensions" }] }),
    { added: [], repair: true });
});
